"""Compact production-only Dashboard page.

The page performs one bounded API request at a time and keeps the last good
payload on transient failures. It contains no Research, replay or virtual
trading controls.
"""

HTML = r'''<!doctype html><html lang="ru"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex,nofollow"><meta name="referrer" content="no-referrer">
<title>APEX V3</title><style>
:root{color-scheme:dark;--bg:#0b0e13;--card:#151a22;--line:#2a3340;--text:#eef2f7;--muted:#95a0b1;--good:#45d18a;--warn:#f0c760;--bad:#ff6b78;--accent:#77a7ff}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.45 system-ui,sans-serif}main{max-width:1450px;margin:auto;padding:18px}.top,.tabs,.filters{display:flex;gap:9px;flex-wrap:wrap;align-items:center}.top{justify-content:space-between}.title{font-size:24px;font-weight:800}.muted{color:var(--muted)}.tabs,.filters{margin:14px 0}.btn,input,select{background:#10151d;color:var(--text);border:1px solid var(--line);border-radius:9px;padding:9px 11px}.btn{cursor:pointer}.btn.active{border-color:var(--accent);background:#17243a}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px}.cols{display:grid;grid-template-columns:1fr 1fr;gap:12px}.card{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:13px;margin-top:12px}.num{font-size:24px;font-weight:800}.good{color:var(--good)}.warn{color:var(--warn)}.bad{color:var(--bad)}.badge{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:2px 7px;margin:2px}.item{border:1px solid var(--line);border-radius:9px;padding:9px;margin-top:8px}.table{overflow:auto}.table table{width:100%;min-width:1050px;border-collapse:collapse}.table th,.table td{padding:9px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}.table th{position:sticky;top:0;background:#171d27}.view{display:none}.view.active{display:block}.error{padding:10px;border:1px solid var(--bad);border-radius:9px}.footer{margin:18px 0}.details{white-space:pre-wrap;max-height:360px;overflow:auto}.heat{height:8px;background:var(--line);border-radius:6px;overflow:hidden}.heat i{display:block;height:100%;background:var(--accent)}
@media(max-width:900px){.cols{grid-template-columns:1fr}}
</style></head><body><main><div class="top"><div><div class="title">APEX V3 · Production</div><div class="muted" id="cohort">Stable live cohort</div></div><div id="updated" class="muted">Загрузка…</div></div>
<div class="tabs" id="tabs"><button class="btn active" data-view="overview">Overview</button><button class="btn" data-view="strategies">Strategies</button><button class="btn" data-view="trades">Trades</button><button class="btn" data-view="manager">Manager</button><button class="btn" data-view="executionView">Execution</button><button class="btn" data-view="market">Market</button><button class="btn" data-view="learning">Learning</button><button class="btn" data-view="health">Health</button></div>
<div class="filters"><select id="strategy"><option value="">Все стратегии</option><option>FAST</option><option>MTF</option><option>ZONE</option><option>SWING</option><option>WYCKOFF</option></select><input id="symbol" placeholder="BTCUSDT"><select id="outcome"><option value="">Все решения</option><option>CANDIDATE</option><option>FILTERED</option><option>PENDING_LTF</option><option>ERROR</option></select><input id="fromdate" type="date" aria-label="Дата с"><input id="todate" type="date" aria-label="Дата по"><button id="apply" class="btn">Применить</button><button id="refresh" class="btn">↻</button></div>
<div id="error"></div><section id="overview" class="view active"><div id="summary" class="grid"></div><div class="cols"><div class="card"><h3>System</h3><div id="system"></div></div><div class="card"><h3>Execution</h3><div id="execution"></div></div></div></section>
<section id="strategies" class="view"><div class="card"><h3>Воронка пяти стратегий</h3><div id="funnels"></div></div><div class="card"><h3>Статистика реальных сделок</h3><div id="tradeStats"></div></div></section>
<section id="trades" class="view"><div class="card table"><table><thead><tr><th>Время</th><th>Стратегия</th><th>Пара</th><th>Решение</th><th>Причина</th><th>Entry</th><th>SL</th><th>TP1</th><th>TP2</th><th>RR</th><th>Путь</th></tr></thead><tbody id="rows"></tbody></table></div></section>
<section id="manager" class="view"><div class="card"><h3>Только подтверждённые позиции</h3><div id="managerRows"></div></div></section>
<section id="executionView" class="view"><div class="cols"><div class="card"><h3>Binance execution</h3><div id="executionRows"></div></div><div class="card"><h3>Fill accounting</h3><div id="accounting"></div></div></div></section>
<section id="market" class="view"><div class="cols"><div class="card"><h3>Gate freshness</h3><div id="marketRows"></div></div><div class="card"><h3>LIVE_CONTEXT · подключения, функции и лимиты</h3><div id="sources"></div></div></div></section>
<section id="learning" class="view"><div class="cols"><div class="card"><h3>Live evidence only</h3><div id="learningStats"></div></div><div class="card"><h3>Groq calibration</h3><div id="calibration"></div></div></div></section>
<section id="health" class="view"><div class="card"><h3>Production function health</h3><div id="functionHealth"></div></div><div class="cols"><div class="card"><h3>Incidents</h3><div id="incidents"></div></div><div class="card"><h3>Versions</h3><div id="versions"></div></div></div></section>
<div class="footer muted">Dashboard только показывает production-факты. Он не меняет Entry, SL, TP, RR, gates, risk, Groq или Binance.</div></main><script>
const TOKEN=new URLSearchParams(location.search).get('key')||'';let LAST=null,controller=null;
const e=s=>String(s??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const n=v=>v===null||v===undefined||v===''?'—':Number(v).toLocaleString('ru-RU',{maximumFractionDigits:8});
function item(title,body,meta=''){return `<div class="item"><b>${e(title)}</b><div>${body}</div>${meta?`<div class="muted">${e(meta)}</div>`:''}</div>`}
function params(){const p=new URLSearchParams({key:TOKEN,days:'30',release:'current',page:'1',page_size:'100'});for(const id of ['strategy','symbol','outcome','fromdate','todate']){const v=document.getElementById(id).value.trim();if(v)p.set(id,v)}return p}
async function load(){if(controller)controller.abort();controller=new AbortController();const timer=setTimeout(()=>controller.abort(),12000);try{const r=await fetch('/api/dashboard?'+params(),{signal:controller.signal});if(!r.ok)throw new Error('HTTP '+r.status);const data=await r.json();LAST=data;render(data)}catch(x){error.innerHTML=`<div class="error">Статистика временно недоступна: ${e(x.name==='AbortError'?'timeout':x.message)}${LAST?' · показан последний успешный снимок':''}</div>`}finally{clearTimeout(timer)}}
function render(d){const dc=d.dashboard_cache||{},stale=String(dc.status||'').includes('STALE');error.innerHTML=stale?`<div class="error"><b>Данные устарели.</b> Показан сохранённый снимок возрастом ${n(Math.round(Number(dc.age_seconds||0)/60))} мин.; выполняется безопасное обновление.</div>`:'';updated.textContent='Обновлено '+e((d.generated_at||'').replace('T',' ').slice(0,19))+' UTC';cohort.textContent='Baseline '+e((d.baseline_utc||d.baseline_started_at||'—').replace('T',' ').slice(0,19))+' · release '+e(String(d.runtime_release_sha||d.release_sha||'—').slice(0,8));const s=d.summary||{};summary.innerHTML=[['Проверок',s.attempts],['Кандидатов',s.candidates],['Ожидают LTF',s.pending_ltf],['Groq approve',s.groq_approve],['Доставлено',s.delivered],['Инцидентов',(d.incidents||[]).length]].map(x=>`<div class="card"><div class="muted">${e(x[0])}</div><div class="num">${n(x[1]||0)}</div></div>`).join('');const o=d.system_overview||{};system.innerHTML=`<b class="${o.state==='HEALTHY'?'good':o.state==='CRITICAL'?'bad':'warn'}">${e(o.state||'UNKNOWN')}</b><div>Gate ${n(o.market_data_ok||0)}/${n(o.market_data_total||0)} · Manager cycles ${n(o.manager_cycles||0)}</div><div class="muted">${e((o.observability_reasons||[]).join(', ')||'No reported blocker')}</div>`;const ex=d.execution_mode||{},eh=d.execution_health||{};execution.innerHTML=`<b>${e(String(ex.mode||'unknown').toUpperCase())}</b> · enabled ${ex.enabled?'yes':'no'} · armed ${ex.live_armed?'yes':'no'}<div>${Object.entries(eh.statuses||{}).map(([k,v])=>`<span class="badge">${e(k)} ${n(v)}</span>`).join('')}</div>`;executionRows.innerHTML=Object.entries(eh.statuses||{}).map(([k,v])=>item(k,`count ${n(v)}`)).join('')||'<span class="muted">Нет execution records</span>';const ts=d.trade_stats||{};accounting.innerHTML=`<b>Только confirmed fills</b><div>closed ${n(ts.closed||0)} · wins ${n(ts.wins||0)} · losses ${n(ts.losses||0)} · avg net ${n(ts.avg_r)}R</div><div class="muted">Fees и funding входят только после подтверждения Binance.</div>`;funnels.innerHTML=(d.funnels||[]).map(x=>item(x.strategy,`start ${n(x.attempts)} → candidates ${n(x.candidates)} → Groq ${n(x.groq)} → delivered ${n(x.delivered)}`,(x.steps||[]).map(y=>`${y.label}: ${y.passed}/${y.reached}`).join(' · '))).join('')||'<span class="muted">Нет данных</span>';tradeStats.innerHTML=(d.trade_stats?.by_strategy||d.trade_stats||[]).map?.(x=>item(x.strategy,`opened ${n(x.opened)} · closed ${n(x.closed)} · wins ${n(x.wins)} · losses ${n(x.losses)} · WR ${n(x.win_rate)}% · net ${n(x.realized_r)}R`)).join('')||'<span class="muted">Нет закрытых live-сделок</span>';rows.innerHTML=(d.rows||[]).map(x=>{const c=x.candidate||{},st=x.stop||{},snap=st.snapshot||{},path=x.decision_path||{};return `<tr><td>${e((x.finished_at||x.occurred_at||'').replace('T',' ').slice(0,19))}</td><td>${e(x.strategy)}</td><td>${e(x.symbol)}</td><td>${e(x.outcome)}</td><td>${e(st.code||st.label||'—')}</td><td>${n(c.entry??snap.entry)}</td><td>${n(c.sl??snap.sl)}</td><td>${n(c.tp1??snap.tp1)}</td><td>${n(c.tp2??snap.tp2)}</td><td>${n(c.rr??x.rr_value)}</td><td><details><summary>checks</summary><div class="details">${e(JSON.stringify(path.steps||x.checks||[],null,2))}</div></details></td></tr>`}).join('')||'<tr><td colspan="11" class="muted">Нет строк</td></tr>';const m=d.manager_db||{};managerRows.innerHTML=(m.trades||[]).map(x=>item(`${x.strategy} · ${x.symbol}`,`${e(x.manager_state)} · ${n(x.current_r)}R · ${e(x.last_action||'HOLD')}`,x.updated_at||'')).join('')||'<span class="muted">Нет сопровождаемых позиций</span>';marketRows.innerHTML=(d.market_data?.rows||[]).map(x=>item(`${x.symbol} · ${x.timeframe}`,`<span class="${x.status==='OK'&&x.freshness_status==='FRESH'?'good':'warn'}">${e(x.status)} · ${e(x.freshness_status)}</span>`,`${x.source||'Gate'} · last closed ${x.last_closed_candle_at||'—'}`)).join('')||'<span class="muted">Нет market health</span>';sources.innerHTML=(d.source_registry||[]).map(x=>item(x.source,`${e(x.mode)} · ${e(x.status||'')}`,x.provenance||'')).join('')||'<span class="muted">Контекст ещё не опубликован</span>';const l=d.learning_v2||{};learningStats.innerHTML=`<b>Authority: ADVISORY</b><div>samples ${n(l.samples||l.total||0)} · confidence ${e(l.confidence||'INSUFFICIENT')}</div><div class="muted">Не блокирует strategy и не увеличивает risk.</div>`;const g=d.groq||{};calibration.innerHTML=Object.entries(g.decisions||{}).map(([k,v])=>`<span class="badge">${e(k)} ${n(v)}</span>`).join('')||'<span class="muted">Нет подтверждённых решений</span>';incidents.innerHTML=(d.incidents||[]).map(x=>{const details=x.details&&typeof x.details==='object'?Object.entries(x.details).map(([k,v])=>`${k}=${v}`).join(', '):'';return item(`${x.severity} · ${x.component}`,e(x.code||'UNKNOWN'),`${x.started_at||''}${x.count>1?' · ×'+n(x.count):''}${details?' · '+e(details):''}`)}).join('')||'<span class="good">Открытых инцидентов нет</span>';versions.innerHTML=Object.entries(d.versions||{}).map(([k,v])=>`<span class="badge">${e(k)}: ${e(v)}</span>`).join('')||'<span class="muted">Нет manifest</span>';const fh=d.function_health||{},fr=fh.rows||[];functionHealth.innerHTML=`<div><b class="${fh.ready?'good':'warn'}">${e(fh.runtime_status||'UNKNOWN')}</b> · new entries ${e(fh.new_entries||'—')}</div>`+fr.map(x=>{const ok=['READY','FRESH','HEALTHY','ACTIVE','AVAILABLE'].includes(x.status),bad=['FAILED','ERROR','BLOCKED','UNAVAILABLE'].includes(x.status);return item(`${x.category} · ${x.function}`,`<span class="${ok?'good':bad?'bad':'warn'}">${e(x.status)}</span>`,`${x.reason_code||''}${x.updated_at?' · '+x.updated_at:''}${x.remaining_day!==undefined&&x.remaining_day!==null?' · remaining '+x.remaining_day:''}`)}).join('')}
tabs.onclick=x=>{const b=x.target.closest('button[data-view]');if(!b)return;document.querySelectorAll('#tabs .btn').forEach(y=>y.classList.toggle('active',y===b));document.querySelectorAll('.view').forEach(y=>y.classList.toggle('active',y.id===b.dataset.view))};apply.onclick=load;refresh.onclick=load;load();setInterval(load,60000);
</script></body></html>'''
